 p_id=>11
,p_name=>'Opening'
,p_javascript_code_onload=>wwv_flow_string.join(wwv_flow_t_varchar2(
'// Author: Clive Bostock',
'// Date: 08-Nov-2026',
'// Purpose: Preserve observed subject state during video dialog and link operations.',
'// Usage: Opening/Gambit page related-video actions.',
'window.chessVideoToken = Array.from(crypto.getRandomValues(new Uint8Array(16)), function(value) { return value.toString(16).padStart(2,"0"); }).join("").replace(/^(.{8})(.{4})(.{4})(.{4})(.{12})$/, "$1-$2-$3-$4-$5");',
'window.chessVideoPending = false;',
'apex.jQuery(apex.gPageContext$).on("apexbeforepagesubmit.chessVideo", function() {',
'  if (window.chessVideoPending) { apex.message.alert("Wait for the video action to finish before saving."); return false; }',
'});',
'window.chessVideoAction = function(action, video, videoVersion) {',
'  if (window.chessVideoPending) { apex.message.alert("Wait for the current video action to finish."); return; }',
'  var id = apex.item("P11_OPENING_ID").getValue(), expected = apex.item("P11_ROW_VERSION").getValue(), token = window.chessVideoToken;',
'  function apply(data) {',
'    if (String(data.subjectId) === String(apex.item("P11_OPENING_ID").getValue()) && String(data.expected) === String(apex.item("P11_ROW_VERSION").getValue()) && data.token === window.chessVideoToken) {',
'      if (data.version) { apex.item("P11_ROW_VERSION").setValue(data.version); }',
'      apex.region("related_videos").refresh();',
'    }',
'  }',
'  if (!id) { apex.message.alert("Save this opening before adding videos."); return; }',
'  if (action === "UNLINK") { apex.message.confirm("Unlink this video? The shared video will be retained.", function(ok) { if (ok) { request(); } }); } else { request(); }',
'  function request() { window.chessVideoPending = true; apex.server.process("SUBJECT_VIDEO", {x01:action,x02:video || "",x03:videoVersion || "",x04:expected,x05:token,x06:id}, {dataType:"json",success:function(data) {',
'    if (!data || data.error || (action === "DIALOG" ? !data.url : !/^[1-9][0-9]*$/.test(String(data.version)))) { apex.message.alert("The video action did not complete. Refresh the saved subject and try again."); return; }',
'    if (data.url) { apex.navigation.dialog(data.url, {title:"Video",modal:true}, "t-Dialog-page--standard", apex.jQuery("#related_videos")); } else { apply(data); }',
'  },error:function() { apex.message.alert("The video action failed. Refresh the saved subject and try again."); },complete:function() { window.chessVideoPending = false; } }); }',
'  apex.jQuery("#related_videos").off("apexafterclosedialog.chessVideo").on("apexafterclosedialog.chessVideo", function(event, data) {',
'    if (data && data.P41_ORIGIN_TOKEN === token && String(data.P41_ORIGIN_ID) === String(id) && String(data.P41_ORIGIN_EXPECTED) === String(expected)) {',
'      apply({subjectId:id,expected:expected,token:token,version:data.P41_ORIGIN_NEW_VERSION});',
'    }',
'  });',
'};')) || chr(10) || wwv_flow_string.join(wwv_flow_t_varchar2(
'apex.jQuery("body").on("apexafterclosedialog.chessVideoNavigation", function(event,data) {',
'  if (data && (data.targetPage === 11 || data.targetPage === 21 || data.targetPage === 31) && /^\d+$/.test(String(data.targetId))) {',
'    apex.server.process("VIDEO_SUBJECT_URL", {x01:data.targetPage,x02:data.targetId}, {dataType:"json",success:function(result) {if (data.targetPage === 31) {apex.navigation.dialog(result.url,{title:"Variation",modal:true});} else {apex.navigation.redirect(result.url);}}});',
'  }',
'});'))
,p_step_title=>'Opening'
,p_autocomplete_on_off=>'OFF'
,p_page_template_options=>'#DEFAULT#'
,p_required_role=>wwv_flow_imp.id(21969436581161538)
,p_protection_level=>'C'
-- BEGIN GENERATED ECO CSS_11
,p_inline_css=>wwv_flow_string.join(wwv_flow_t_varchar2(
'.chess-eco-list { display: flex; flex-wrap: wrap; align-items: flex-start; gap: .5rem; }',
'.chess-eco-list > details { flex: 0 1 auto; min-width: 0; max-width: 100%; }',
