,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'  l_html clob := ''<div class="t-Region-body">'';',
'  l_duration varchar2(40);',
'begin',
'  if :P11_OPENING_ID is null then return ''<p>Save this opening before adding videos.</p>''; end if;',
'  l_html := l_html || ''<p><button type="button" class="t-Button" onclick="chessVideoAction(''''DIALOG'''')">Create video</button></p><ul class="t-LinksList">'';',
'  for r in (select v.* from orac_chess.chess_video_v v join orac_chess.chess_video_opening_v m on m.video_id=v.video_id where m.opening_id=:P11_OPENING_ID order by v.title) loop',
'    l_duration := case when r.duration_seconds is null then null when r.duration_seconds < 3600 then to_char(trunc(r.duration_seconds/60),''FM00'') || '':'' || to_char(mod(r.duration_seconds,60),''FM00'') else to_char(trunc(r.duration_seconds/3600),''FM9999999990'') || '':'' || to_char(trunc(mod(r.duration_seconds,3600)/60),''FM00'') || '':'' || to_char(mod(r.duration_seconds,60),''FM00'') end;',
'    l_html := l_html || ''<li><strong>'' || apex_escape.html(r.title) || ''</strong> - '' || apex_escape.html(r.creator) || '' '' || apex_escape.html(l_duration);',
'    if regexp_like(r.video_url,''^https?://'',''i'') then l_html := l_html || '' <a target="_blank" rel="noopener noreferrer" href="'' || apex_escape.html_attribute(r.video_url) || ''">Watch</a>''; end if;',
'    l_html := l_html || '' <button type="button" class="t-Button t-Button--small" onclick="chessVideoAction(''''DIALOG'''','' || r.video_id || '')">Edit video</button> <button type="button" class="t-Button t-Button--small" onclick="chessVideoAction(''''UNLINK'''','' || r.video_id || '','' || r.row_version || '')">Unlink</button></li>'';',
'  end loop;',
'  l_html := l_html || ''</ul><details><summary>Link existing video</summary><label for="video_search">Search videos</label><input id="video_search" type="search" oninput="apex.region(''''related_videos'''').element.find(''''.chess-video-choice'''').each(function(){this.hidden=!this.textContent.toLowerCase().includes(document.getElementById(''''video_search'''').value.toLowerCase());})"><ul>'';',
'  for r in (select v.video_id,v.title,v.creator,v.platform,v.row_version from orac_chess.chess_video_v v where not exists (select 1 from orac_chess.chess_video_opening_v m where m.video_id=v.video_id and m.opening_id=:P11_OPENING_ID) order by v.title) loop',
'    l_html := l_html || ''<li class="chess-video-choice">'' || apex_escape.html(r.title) || '' - '' || apex_escape.html(r.creator) || '' - '' || apex_escape.html(r.platform) || '' <button type="button" class="t-Button t-Button--small" onclick="chessVideoAction(''''LINK'''','' || r.video_id || '','' || r.row_version || '')">Link</button></li>'';',
'  end loop;',
'  return l_html || ''</ul></details></div>'';',
'end;'))
,p_plug_source_type=>'NATIVE_DYNAMIC_CONTENT'
