,p_name=>'Default YouTube video ID'
,p_event_sequence=>10
,p_triggering_element_type=>'ITEM'
,p_triggering_element=>'P41_VIDEO_URL,P41_PLATFORM'
,p_bind_type=>'bind'
,p_execution_type=>'IMMEDIATE'
,p_bind_event_type=>'change'
);
wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(84715302036390902)
,p_event_id=>wwv_flow_imp.id(84715302036390901)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'(function defaultYouTubeVideoId() {',
'    // Author: Clive Bostock; Date: 07-Nov-2026',
'    // Purpose: Default the editable video ID from a recognised YouTube URL.',
'    // Usage: Video page URL or Platform change dynamic action.',
'    if (apex.item("P41_PLATFORM").getValue() !== "YouTube") { return; }',
'    var value = apex.item("P41_VIDEO_URL").getValue();',
'    if (!/^https?:\/\//i.test(value) || /[\x00-\x20\x7f]/.test(value)) { return; }',
'    var url;',
'    try { url = new URL(value); }',
'    catch (error) { return; }',
'    if (!["http:", "https:"].includes(url.protocol) || url.username || url.password) { return; }',
'    var id = null;',
'    if (["youtube.com", "www.youtube.com", "m.youtube.com"].includes(url.hostname)) {',
'        if (url.pathname === "/watch" && url.searchParams.getAll("v").length === 1) {',
'            id = url.searchParams.get("v");',
'        } else {',
'            var path = url.pathname.match(/^\/(?:shorts|embed)\/([A-Za-z0-9_-]{11})\/?$/);',
'            if (path) { id = path[1]; }',
'        }',
'    } else if (["youtu.be", "www.youtu.be"].includes(url.hostname)) {',
'        var shortPath = url.pathname.match(/^\/([A-Za-z0-9_-]{11})\/?$/);',
'        if (shortPath) { id = shortPath[1]; }',
'    }',
'    if (id && /^[A-Za-z0-9_-]{11}$/.test(id)) {',
'        apex.item("P41_EXTERNAL_VIDEO_ID").setValue(id);',
'    }',
'}());'))
);
