 p_id=>wwv_flow_imp.id(27430604072875035)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Save video'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'  l_version number;',
'  l_duration_seconds number;',
'  l_published_on date;',
'  function parse_duration(p_value varchar2) return number is',
'    l_seconds number;',
'    l_parts number;',
'  begin',
'    if p_value is null then return null; end if;',
'    if not regexp_like(p_value, ''^[0-9]+:[0-5][0-9]$|^[0-9]+:[0-5][0-9]:[0-5][0-9]$'', ''c'')',
'       or length(p_value) > 20 then',
'      raise value_error;',
'    end if;',
'    l_parts := regexp_count(p_value, '':'');',
'    if l_parts = 1 then',
'      l_seconds := to_number(regexp_substr(p_value, ''[0-9]+'', 1, 1)) * 60',
'                 + to_number(regexp_substr(p_value, ''[0-9]+'', 1, 2));',
'    else',
'      l_seconds := to_number(regexp_substr(p_value, ''[0-9]+'', 1, 1)) * 3600',
'                 + to_number(regexp_substr(p_value, ''[0-9]+'', 1, 2)) * 60',
'                 + to_number(regexp_substr(p_value, ''[0-9]+'', 1, 3));',
'    end if;',
'    if l_seconds < 1 or l_seconds > 9999999999 then raise value_error; end if;',
'    return l_seconds;',
'  end parse_duration;',
'begin',
'  begin',
'    l_duration_seconds := parse_duration(:P41_DURATION_SECONDS);',
'  exception when value_error then',
'    apex_error.add_error(p_message => ''Enter duration as MM:SS or HH:MM:SS, from 00:01 up to 9999999999 seconds.'', p_display_location => apex_error.c_inline_with_field_and_notif, p_page_item_name => ''P41_DURATION_SECONDS'');',
'    return;',
'  end;',
'  begin',
'    l_published_on := to_date(:P41_PUBLISHED_ON,''FXDD-Mon-YYYY'',''NLS_DATE_LANGUAGE=English'');',
'  exception when others then',
'    apex_error.add_error(p_message => ''Enter a valid date as DD-Mon-YYYY, for example 07-Nov-2026.'', p_display_location => apex_error.c_inline_with_field_and_notif, p_page_item_name => ''P41_PUBLISHED_ON'');',
'    return;',
'  end;',
'  if :P41_VIDEO_ID is null and :P41_ORIGIN_TYPE is not null then',
'    orac_chess.chess_admin_api.create_video_for_subject(:P41_PLATFORM,:P41_EXTERNAL_VIDEO_ID,:P41_VIDEO_URL,:P41_TITLE,:P41_CREATOR,:P41_DESCRIPTION,l_duration_seconds,l_published_on,:P41_ORIGIN_TYPE,:P41_ORIGIN_ID,coalesce(:P41_ORIGIN_NEW_VERSION,:P41_ORIGIN_EXPECTED),:P41_VIDEO_ID,:P41_ORIGIN_NEW_VERSION,l_version);',
'  else',
'    orac_chess.chess_admin_api.save_video(:P41_VIDEO_ID, :P41_ROW_VERSION, :P41_PLATFORM, :P41_EXTERNAL_VIDEO_ID, :P41_VIDEO_URL, :P41_TITLE, :P41_CREATOR, :P41_DESCRIPTION, l_duration_seconds, l_published_on, l_version);',
'  end if;',
'  :P41_ROW_VERSION := l_version;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>'SAVE'
,p_process_when_type=>'REQUEST_IN_CONDITION'
,p_internal_uid=>50000000000100131
);
